// apps/web/src/modules/13-emar — the M13 read/WRITE access layer the §6.1 screens share
// (Track B / ADR-0030, ADR-0032; F-031).
//
// Every wire shape below is a TYPE ALIAS into the generated `operations` map
// (packages/ui/src/core/api/schema.ts, regenerated by `bun run client:gen` from the M13 request/response
// TypeBox schemas in scripts/openapi/enrichments.ts) — never a hand-copied interface. That is what lets
// each call go through with no `as never` cast: the argument and return types ARE the server contract, so
// a route or DTO drift is a compile error here rather than a runtime surprise in a screen.
//
// Until F-031 there was nothing to alias for a write: the M13 enrichments carried `body` and no
// `response`, so the emitted contract gave every write a bare `200: OK` with `content?: never` and the
// generated client typed each returned row as `never`. The response schemas are published now (and at the
// route's REAL status — eleven of these are 201s), which is the difference between "the screen can commit"
// and "the screen can commit and then show what it committed".
//
// WHAT THE SERVER OWNS, WHICH NOTHING HERE SECOND-GUESSES.
//
//   • §2.2 lifecycle + §2.5 late-entry tier + §2.9 BCMA match. The client sends what it observed (the
//     scan payloads, the administration time); the SERVER derives the tier and the canonical match result.
//     A screen that pre-computed either would be publishing a second opinion about the medical record.
//   • §4.7 ABAC. `administering_clinician_eligible[:medClass]` reads the caller's discipline set from
//     their session role grants — never from anything sent here. A 403 is the answer, not a bug to route
//     around, and it is surfaced verbatim.
//   • §7.2 SUD (42 CFR Part 2). Rows the caller may not see are ABSENT from the reads, never hidden here.
//   • §2.6 D7 double-witness. The witness token is minted by a DIFFERENT clinician's session on their own
//     device and rides as `x-witness-attestation`; this layer only carries it. It is a server-minted,
//     single-use, 60-second bearer credential — the reason `check-request-header-auth.ts` classifies that
//     header `verified` rather than trusting a self-asserted "a witness watched me".
import type { ApiClient, operations } from "@chartwarden/ui";

// ── schema-derived type extraction ─────────────────────────────────────────────────────────────────────

/** The `application/json` payload of an openapi-fetch response/request-body slot. */
type Json<T> = T extends { content: { "application/json": infer B } } ? B : never;
/** The success body of operation `Op` — 200 or 201, whichever the route actually sends (M13 has both). */
type Ok<Op> = Op extends { responses: { 200: infer R } }
  ? Json<R>
  : Op extends { responses: { 201: infer R } }
    ? Json<R>
    : never;
/** The request body of operation `Op` (works whether `requestBody` is required or optional). */
type ReqBody<Op> = Op extends { requestBody?: infer RB } ? Json<RB> : never;
/** The query-parameter object of operation `Op`. */
type ReqQuery<Op> = Op extends { parameters: { query?: infer Q } } ? Q : never;

// ── wire shapes ────────────────────────────────────────────────────────────────────────────────────────

/** §6.1 #11 — one administration row. The shape every write on this surface returns, too. */
export type AdministrationView = Ok<operations["getApiV1AdministrationsById"]>;
/** §6.1 #1 — one cell of the MAR grid. */
export type ScheduledDoseView = Ok<operations["getApiV1Scheduleddoses"]>[number];
/** §6.1 #8 — one missed dose in the patient-scoped inbox. */
export type MissedDoseView = Ok<operations["getApiV1Misseddoses"]>[number];
/** §6.1 #6 — a reconciliation worksheet with its per-line decisions. */
export type WorksheetView = Ok<operations["getApiV1ReconciliationWorksheetsById"]>;
/** One decided line of a worksheet. */
export type ReconciliationDecisionView = WorksheetView["decisions"][number];
/** §6.1 #7 — a comfort-kit deployment. */
export type DeploymentView = Ok<operations["getApiV1ComfortkitsDeploymentsById"]>;
/** §6.1 #5 — an IV continuous session's ordered segment sequence, its derived state and its period. */
export type IvSessionView = Ok<operations["getApiV1AdministrationsIvsessionsBySessionId"]>;
/** §2.11 — the state the segment sequence derives. The client offers only what the graph accepts next. */
export type IvSessionState = IvSessionView["state"];
/** The five `iv_continuous_*` segment kinds. */
export type IvSegmentMode = Exclude<AdministrationMode, "single_dose">;

/**
 * §2.11 — `IV_SESSION_GRAPH`, mirrored for the CLIENT's benefit only. The server runs the real one
 * (`assertIvSegmentLegal` on every write), so this decides which BUTTONS to render and nothing else —
 * the alternative is offering all five segments and letting a clinician discover the illegal ones as
 * 409s at an infusion pump. It is a copy because `apps/web` may not import `@chartwarden/emar` (a backend
 * feature package); the `state` the server publishes is what keeps the two in agreement.
 */
export const IV_NEXT_SEGMENTS: Readonly<Record<IvSessionState, readonly IvSegmentMode[]>> = {
  none: ["iv_continuous_start"],
  running: ["iv_continuous_rate_change", "iv_continuous_pause", "iv_continuous_stop"],
  paused: ["iv_continuous_resume", "iv_continuous_stop"],
  stopped: [],
};
/** §6.1 #12 — the tenant administration policy. */
export type AdministrationPolicyView = Ok<operations["getApiV1AdminAdministrationpolicy"]>;

/** M12's medication-order projection — the DRUG the eMAR grid names. Read over the M12 route (an HTTP
 *  call, not an import: apps/web modules own disjoint codePaths and never compile-depend on each other).
 *  Before this the grid printed a truncated medication-order UUID where a drug name belongs, because the
 *  M13 dose DTO carries only the order id; joining it to this list is what makes the row legible. */
export type ActiveMedicationOrder = Ok<operations["getApiV1Medicationorders"]>["orders"][number];

/** The M12 lifecycle status of an order. */
export type MedicationOrderStatus = ActiveMedicationOrder["status"];

/**
 * The order statuses the eMAR may record an administration against — M12's `ADMINISTRABLE_STATUSES`,
 * mirrored so the picker offers only doses that can actually be given.
 *
 * `active` is the obvious one. `verbal_pending` is here because M12 §2.3 says a verbal order "is active
 * for clinical execution during this window" and "M13 eMAR may record administrations" — the 2 AM
 * verbal-order workflow, which is the case the whole module names as its reason to exist.
 *
 * This mirror is a DISPLAY decision only; M13's §2.9 D6 gate is the enforcement and it reads M12's own
 * verdict per order. It is a copy rather than an import because `apps/web` modules do not compile
 * against the backend. Until F-058 this list had to be an EXCLUSION list — everything but the terminal
 * statuses — because nothing in the platform ever activated an order and an inclusion list would have
 * emptied the picker for every patient alive.
 */
const ADMINISTRABLE_ORDER_STATUSES: readonly MedicationOrderStatus[] = ["active", "verbal_pending"];

/** The §2.1 administration mode discriminator (single dose + the five IV-continuous segment kinds). */
export type AdministrationMode = ReqBody<operations["postApiV1Administrations"]>["mode"];
/** The medication-class taxonomy the §4.7 ABAC floor is parameterized by. */
export type MedClass = ReqBody<operations["postApiV1Administrations"]>["medClass"];
/** §2.4 — who asked for the PRN dose. */
export type PrnRequestedByKind = NonNullable<
  ReqBody<operations["postApiV1Administrations"]>["prn"]
>["requestedByKind"];
/** §2.8 D17 — the per-line reconciliation decision vocabulary. */
export type ReconciliationDecisionKind = ReqBody<
  operations["postApiV1ReconciliationWorksheetsByIdDecisions"]
>["decision"];
/** §2.8 D17 — which source produced this worksheet line: an active M12 order, an M12 MedHx pull, or a
 *  caregiver-reported home medication with no order behind it. */
export type ReconciliationLineKind = ReqBody<
  operations["postApiV1ReconciliationWorksheetsByIdDecisions"]
>["lineKind"];
/** The body of the record route — assembled by the ceremony, sent verbatim. */
export type RecordAdministrationBody = ReqBody<operations["postApiV1Administrations"]>;
/** §2.9 BCMA — the optional bedside scan. The server re-derives the canonical `barcodeMatchResult`. */
export type BarcodeScan = NonNullable<RecordAdministrationBody["barcodeScan"]>;

// ── request helpers ────────────────────────────────────────────────────────────────────────────────────

/**
 * Turn a failed response into a sentence a clinician at a bedside can act on. The server's problem+json
 * body is the source of truth; the status-derived fallbacks name the contracts this surface can actually
 * violate. 403 is deliberately NOT softened into "something went wrong": on an eMAR it means the §4.7
 * discipline matrix refused this class of medication to this caller, and the honest reading of that is
 * "someone else has to give this dose", not "try again".
 */
export function errorMessage(error: unknown, fallback: string): string {
  const body = error as
    | { title?: string; detail?: string; code?: string; status?: number }
    | null
    | undefined;
  if (body?.detail) return body.detail;
  if (body?.title) return body.title;
  if (body?.status === 403)
    return "You do not hold the authority this action requires for this medication.";
  if (body?.status === 412)
    return "This record changed while you were working on it. Reload and re-apply your entry.";
  return fallback;
}

/** A wristband-driven BCMA refusal (GAP-020): the machine `code` (`WRISTBAND_NOT_ON_FILE`, ...) and its sentence. */
export interface WristbandRefusal {
  readonly code: string;
  readonly message: string;
}

/**
 * The wristband reason behind a `BARCODE_VERIFICATION_FAILED`, read from the error envelope's `details`, or null
 * when the refusal is about something else (wrong drug, expired). The UI uses the code to say what to DO:
 * print a band, scan the new one, or rescan.
 */
export function wristbandRefusalOf(error: unknown): WristbandRefusal | null {
  const body = error as
    | { error?: { details?: { code?: string; message?: string }[] } }
    | null
    | undefined;
  const hit = body?.error?.details?.find(
    (d) => typeof d.code === "string" && d.code.startsWith("WRISTBAND_"),
  );
  return hit?.code ? { code: hit.code, message: hit.message ?? hit.code } : null;
}

/** True when the failure is the §2.6 D7 refusal to commit a controlled substance without a live witness
 *  token — the one 422 whose remedy is a second clinician rather than a corrected field. */
export function isWitnessRequired(error: unknown): boolean {
  const body = error as { code?: string; detail?: string } | null | undefined;
  if (body?.code === "WITNESS_REQUIRED") return true;
  return typeof body?.detail === "string" && /witness/i.test(body.detail);
}

// ── reads ──────────────────────────────────────────────────────────────────────────────────────────────

/** §6.1 #1 — the scheduled-dose timeline the MAR grid is built from. */
export async function listScheduledDoses(
  client: ApiClient,
  query: ReqQuery<operations["getApiV1Scheduleddoses"]>,
): Promise<{ doses: ScheduledDoseView[]; error: unknown }> {
  const res = await client.GET("/api/v1/scheduled-doses", { params: { query } });
  if (res.error) return { doses: [], error: res.error };
  return { doses: res.data ?? [], error: null };
}

/** §6.1 #1 — the recent-administrations strip. */
export async function listAdministrations(
  client: ApiClient,
  query: ReqQuery<operations["getApiV1Administrations"]>,
): Promise<{ administrations: AdministrationView[]; error: unknown }> {
  const res = await client.GET("/api/v1/administrations", { params: { query } });
  if (res.error) return { administrations: [], error: res.error };
  return { administrations: res.data ?? [], error: null };
}

/** §6.1 #11 — one administration inside the retention-class-C audit boundary. */
export async function getAdministration(
  client: ApiClient,
  id: string,
): Promise<{ administration: AdministrationView | null; error: unknown }> {
  const res = await client.GET("/api/v1/administrations/{id}", { params: { path: { id } } });
  if (res.error) return { administration: null, error: res.error };
  return { administration: res.data, error: null };
}

/** M12 — the patient's administrable medication orders (see {@link ADMINISTRABLE_ORDER_STATUSES}). A
 *  caller without `prescribing.read` gets an error here and the screens degrade to the order id rather
 *  than fabricating a drug name. */
export async function listPatientMedicationOrders(
  client: ApiClient,
  patientId: string,
): Promise<{ orders: ActiveMedicationOrder[]; error: unknown }> {
  const res = await client.GET("/api/v1/medication-orders", {
    params: { query: { patientId } },
  });
  if (res.error) return { orders: [], error: res.error };
  return {
    orders: (res.data?.orders ?? []).filter((o) => ADMINISTRABLE_ORDER_STATUSES.includes(o.status)),
    error: null,
  };
}

